describe('Table Loading State', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(2000);
      });
    }).as('fetchData');
  });

  it('should display loading state while data is fetching', () => {
    cy.get('[data-testid="table-container"]').should('exist');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Loading');
    cy.get('[data-testid="table-body"]').should('not.exist');

    cy.wait('@fetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-body"]').should('be.visible');
  });

  it('should hide loading state and display table data after fetch completes', () => {
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@fetchData');

    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-body"] tr').should('have.length.greaterThan', 0);
    cy.get('[data-testid="table-body"] td').first().should('not.be.empty');
  });

  it('should display loading state on table refresh', () => {
    cy.wait('@fetchData');
    cy.get('[data-testid="table-body"]').should('be.visible');

    cy.get('[data-testid="refresh-button"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="table-body"]').should('not.exist');

    cy.wait('@fetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-body"]').should('be.visible');
  });

  it('should handle loading state with skeleton loaders', () => {
    cy.get('[data-testid="skeleton-loader"]').should('be.visible');
    cy.get('[data-testid="skeleton-loader"]').should('have.length.greaterThan', 0);

    cy.wait('@fetchData');
    cy.get('[data-testid="skeleton-loader"]').should('not.exist');
    cy.get('[data-testid="table-body"]').should('be.visible');
  });

  it('should maintain loading state during slow network conditions', () => {
    cy.intercept('GET', '/api/data', (req) => {
      req.reply((res) => {
        res.delay(5000);
      });
    }).as('slowFetchData');

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-text"]').should('contain', 'Loading');

    cy.wait(2000);
    cy.get('[data-testid="loading-spinner"]').should('still.be.visible');

    cy.wait('@slowFetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should display loading state with accessibility attributes', () => {
    cy.get('[data-testid="loading-spinner"]')
      .should('have.attr', 'role', 'status');
    cy.get('[data-testid="loading-spinner"]')
      .should('have.attr', 'aria-live', 'polite');
    cy.get('[data-testid="loading-text"]')
      .should('have.attr', 'aria-label')
      .and('include', 'Loading');
  });

  it('should handle loading state when table has pagination', () => {
    cy.wait('@fetchData');
    cy.get('[data-testid="pagination-next"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="table-body"]').should('not.exist');

    cy.wait('@fetchData');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
    cy.get('[data-testid="table-body"]').should('be.visible');
  });
});
